-- Generated by generate_class_creation.py from class_creation.csv, class_map.csv and the stock CharBaseInfo.dbc:
-- every race can create a Demon Hunter (WoW class 3, a stock slot). Stock has no row for races 1,5,7; the core
-- refuses a pair with no playercreateinfo row. Each new row is at the hub, as world_0028's; the class start
-- (dc_class_start, class-keyed) gives the kit and skills to every race alike. Racial stats are per race in the
-- pinned core, so no stats rows are needed. Idempotent.
SET NAMES utf8mb4;
INSERT INTO `playercreateinfo` (`race`,`class`,`map`,`zone`,`position_x`,`position_y`,`position_z`,`orientation`)
SELECT r.`race`,3,h.`map_id`,h.`area_id`,h.`x`,h.`y`,h.`z`,h.`o` FROM (SELECT 1 AS `race` UNION ALL SELECT 5 UNION ALL SELECT 7) r JOIN `dc_world_hub` h ON h.`id`=1
ON DUPLICATE KEY UPDATE `map`=VALUES(`map`),`zone`=VALUES(`zone`),`position_x`=VALUES(`position_x`),`position_y`=VALUES(`position_y`),`position_z`=VALUES(`position_z`),`orientation`=VALUES(`orientation`);
DELETE FROM `playercreateinfo_action` WHERE `class`=3 AND `race` IN (1,5,7);
INSERT INTO `playercreateinfo_action` (`race`,`class`,`button`,`action`,`type`)
SELECT r.`race`, 3, a.`button`, a.`action`, a.`type` FROM (SELECT 1 AS `race` UNION ALL SELECT 5 UNION ALL SELECT 7) r
JOIN `playercreateinfo_action` a ON a.`class`=3 AND a.`race`=2 AND a.`action`=6603;
